INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM200U6DX', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A photographer charges $13$ dollars per photo print and a flat setup fee of $29$ dollars. If a client has at most $120$ dollars to spend, what is the greatest number of photo prints the client can order?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Let $n$ represent the number of photo prints. The total cost is $13n + 29$, and this must be at most $120$: $$13n + 29 \\leq 120.$$ Subtracting $29$ from both sides gives $13n \\leq 91$. Dividing both sides by $13$ gives $n \\leq 7$. Since $n$ must be a whole number, the greatest number of photo prints is $7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22P2UP1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $g$ is defined by $g(x) = (x - 11)^2 + 7$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The function $g(x) = (x - 11)^2 + 7$ is in vertex form $a(x - h)^2 + k$ with $a = 1 > 0$, $h = 11$, and $k = 7$. Since the coefficient of the squared term is positive, the parabola opens upward and the vertex represents the minimum. The minimum value is $k = 7$, occurring at $x = 11$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23VJJLJ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $14x - 53 = 59$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{7}$"},{"key":"B","text":"$8$"},{"key":"C","text":"$-8$"},{"key":"D","text":"$112$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding $53$ to both sides gives $14x = 112$, and dividing both sides by $14$ gives $x = 8$. The value $\\frac{3}{7}$ results from subtracting $53$ from $59$ to get $6$ and then dividing by $14$, which misapplies the equation by treating it as $14x = 59 - 53$ instead of $14x = 59 + 53$. The value $-8$ results from a sign error, negating the correct answer. The value $112$ results from stopping after computing $14x = 112$ without dividing by $14$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM242QIVG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A biologist takes a random sample of $350$ fish from a lake that contains an estimated $8{,}400$ fish and finds that $29\\%$ of the sampled fish are a particular species. The margin of error for this estimate is $\\pm 4.9$ percentage points. Which of the following is a plausible estimate for the total number of fish of that species in the lake?', NULL, $lyceon_json$[{"key":"A","text":"$1{,}764$"},{"key":"B","text":"$2{,}436$"},{"key":"C","text":"$2{,}940$"},{"key":"D","text":"$3{,}276$"}]$lyceon_json$::jsonb, 'B', NULL, E'The plausible range for the population proportion is $29\\% \\pm 4.9\\%$, giving $24.1\\%$ to $33.9\\%$. Applying this to $8{,}400$ fish: $0.241 \\times 8{,}400 \\approx 2{,}024$ and $0.339 \\times 8{,}400 \\approx 2{,}848$. The value $2{,}436$ equals $0.29 \\times 8{,}400$ and falls squarely within the interval. The value $1{,}764$ equals $0.21 \\times 8{,}400$, which is below the lower bound of the confidence interval, likely resulting from subtracting the margin of error twice. The value $2{,}940$ equals $0.35 \\times 8{,}400$, which exceeds the upper bound of $33.9\\%$. The value $3{,}276$ equals $0.39 \\times 8{,}400$, far above the plausible range, possibly resulting from adding the margin of error to $34\\%$ instead of to $29\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2525N6E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Triangle $DEF$ is similar to triangle $GHJ$, with vertices $D$, $E$, and $F$ corresponding to vertices $G$, $H$, and $J$, respectively. The lengths of sides $DE$, $EF$, and $DF$ are $14$, $21$, and $35$, respectively. If $GH = 6$, what is the perimeter of triangle $GHJ$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30', ARRAY['30'], E'The correct answer is $30$. Since the triangles are similar with $DE$ corresponding to $GH$, the scale factor is $\\frac{GH}{DE} = \\frac{6}{14} = \\frac{3}{7}$. The perimeter of triangle $DEF$ is $14 + 21 + 35 = 70$. The perimeter of triangle $GHJ$ is $70 \\times \\frac{3}{7} = 30$. Alternatively, $HJ = 21 \\times \\frac{3}{7} = 9$ and $GJ = 35 \\times \\frac{3}{7} = 15$, so the perimeter is $6 + 9 + 15 = 30$. A common error is using the reciprocal scale factor $\\frac{7}{3}$ instead of $\\frac{3}{7}$, which gives a perimeter larger than the original. Another error is computing only one side correctly and forgetting to sum all three sides.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25VRVLN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 - 3x - 54 = 0$ and $x > 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Factor the quadratic: $x^2 - 3x - 54 = (x - 9)(x + 6) = 0$. Setting each factor to zero gives $x = 9$ or $x = -6$. Since the problem requires $x > 0$, the answer is $9$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM266EFZ3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A fitness company surveys $85$ of its gym members and finds that members who attend group classes at least three times per week report higher satisfaction scores than those who attend once per week or less. Which of the following conclusions is supported by this study?', NULL, $lyceon_json$[{"key":"A","text":"Attending group classes more frequently causes higher satisfaction."},{"key":"B","text":"There is an association between group class attendance frequency and satisfaction among these gym members."},{"key":"C","text":"All gym members who attend group classes frequently will report high satisfaction."},{"key":"D","text":"The gym should require all members to attend at least three group classes per week."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants were not randomly assigned to different attendance levels, this is an observational study that can identify an association but cannot establish causation. The claim that frequent attendance causes higher satisfaction incorrectly infers causation from an observational design, since confounding factors such as pre-existing motivation could explain the relationship. The claim that all frequent attendees will report high satisfaction overgeneralizes an average trend to every individual. The recommendation that the gym require three classes per week is a policy prescription not supported by an observational finding, and it assumes a causal relationship that the study design cannot confirm.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26NSXT3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A factory produces $137$ widgets in $4$ hours. At this constant rate, how many widgets does the factory produce in $12$ hours?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '411', ARRAY['411'], E'The rate is $\\frac{137}{4}$ widgets per hour. In $12$ hours, the factory produces $\\frac{137}{4} \\times 12 = 137 \\times 3 = 411$ widgets. A common error is to multiply $137 \\times 12 = 1{,}644$, forgetting to account for the $4$-hour base period. Another error is to add $137 + 12 = 149$, treating the relationship as additive rather than multiplicative.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26XR1ZC', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{25x^2 - 81}{5x - 9}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$5x - 9$"},{"key":"B","text":"$5x + 9$"},{"key":"C","text":"$5x$"},{"key":"D","text":"$20x + 9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $25x^2 - 81$ is a difference of squares: $(5x)^2 - (9)^2 = (5x + 9)(5x - 9)$. Dividing by $(5x - 9)$ cancels the common factor, leaving $5x + 9$. The distractor $5x - 9$ results from a sign error, selecting the factor that was cancelled rather than the one that remains. The distractor $5x$ comes from partial reasoning, recognizing $\\sqrt{25x^2} = 5x$ but dropping the constant term entirely. The distractor $20x + 9$ reflects a fundamental misunderstanding of how to simplify a difference of squares after factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26XX0G5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher models the relationship between weekly advertising spending in hundreds of dollars, $x$, and weekly revenue in thousands of dollars, $y$, using the equation $y = 0.38x + 2.1$. At an advertising spending of $1{,}300$ dollars, the observed revenue is $7{,}400$ dollars. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"$-0.36$"},{"key":"B","text":"$0.36$"},{"key":"C","text":"$0.64$"},{"key":"D","text":"$2.36$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $x$ is in hundreds of dollars, $1{,}300$ dollars corresponds to $x = 13$. Since $y$ is in thousands of dollars, $7{,}400$ dollars corresponds to $y = 7.4$. The predicted value is $y = 0.38(13) + 2.1 = 4.94 + 2.1 = 7.04$. The residual is observed minus predicted: $7.4 - 7.04 = 0.36$. The value $-0.36$ results from computing predicted minus observed ($7.04 - 7.4 = -0.36$), reversing the residual formula. The value $0.64$ arises from a miscalculation of the predicted value, such as computing $0.38(13) = 4.94$ but rounding or misadding to get $6.76$, yielding $7.4 - 6.76 = 0.64$. The value $2.36$ results from failing to convert spending to hundreds of dollars, using $x = 1{,}300$ to get a predicted value of $496.1$ in thousands, and then misinterpreting the unit mismatch.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29FJZ1H', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A sector of a circle has a central angle of $\\frac{5\\pi}{9}$ radians and a radius of $27$. What is the area of the sector?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{405\\pi}{2}$"},{"key":"B","text":"$\\frac{405\\pi}{9}$"},{"key":"C","text":"$15\\pi$"},{"key":"D","text":"$405\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{405\\pi}{2}$. The area of a sector is $A = \\frac{1}{2}r^2\\theta$, where $\\theta$ is in radians. Substituting: $A = \\frac{1}{2}(27)^2\\left(\\frac{5\\pi}{9}\\right) = \\frac{1}{2}(729)\\left(\\frac{5\\pi}{9}\\right) = \\frac{1}{2}(405\\pi) = \\frac{405\\pi}{2}$. The value $\\frac{405\\pi}{9}$ results from dividing by $9$ instead of by $2$, confusing the sector formula. The value $15\\pi$ comes from using the arc length formula $s = r\\theta = 27 \\times \\frac{5\\pi}{9} = 15\\pi$ instead of the area formula. The value $405\\pi$ results from omitting the $\\frac{1}{2}$ factor in the sector area formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29YOLI6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ in the equation $$\\frac{5(3x + 11)}{7} = 40\\;?$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'Multiply both sides by $7$ to get $5(3x + 11) = 280$. Divide both sides by $5$ to get $3x + 11 = 56$. Subtract $11$ from both sides: $3x = 45$. Divide by $3$: $x = 15$. A common error is forgetting to distribute the $5$ before clearing the fraction, or mishandling the constant $11$ when isolating $x$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A7W4N4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution to the equation $\\sqrt{5x + 11} = x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-2$ and $5$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $5x + 11 = (x + 1)^2 = x^2 + 2x + 1$. Rearranging: $x^2 - 3x - 10 = 0$, so $(x - 5)(x + 2) = 0$, yielding $x = 5$ or $x = -2$. Since squaring can introduce extraneous solutions, both must be checked. For $x = -2$: $\\sqrt{5(-2) + 11} = \\sqrt{1} = 1$, but $(-2) + 1 = -1$, so $1 \\neq -1$ and $x = -2$ is extraneous. For $x = 5$: $\\sqrt{5(5) + 11} = \\sqrt{36} = 6$, and $5 + 1 = 6$, which checks. The only valid solution is $5$. The distractor $-2$ is the extraneous root that fails the check. The distractor listing both $-2$ and $5$ results from solving the quadratic correctly but failing to check for extraneous solutions. The distractor $-5$ results from a sign error when solving the factored equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ACAETE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Lines $m$ and $n$ are parallel. A transversal crosses line $m$ at point $A$ and line $n$ at point $B$. The acute angle formed between the transversal and line $m$ at point $A$ measures $37^\\circ$. A second transversal crosses line $n$ at point $B$ and makes an angle of $54^\\circ$ with line $n$ on the same side as the first transversal. What is the measure of the angle between the two transversals at point $B$?', NULL, $lyceon_json$[{"key":"A","text":"$17^\\circ$"},{"key":"B","text":"$37^\\circ$"},{"key":"C","text":"$91^\\circ$"},{"key":"D","text":"$143^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $17^\\circ$. Since lines $m$ and $n$ are parallel, the first transversal meets line $n$ at point $B$ forming an alternate interior angle of $37^\\circ$ with line $n$. The second transversal makes a $54^\\circ$ angle with line $n$ at the same point on the same side. The angle between the two transversals at $B$ is $54 - 37 = 17$. The value $37^\\circ$ results from stopping at identifying the alternate interior angle without subtracting the second transversal''s angle. The value $91^\\circ$ comes from incorrectly adding the two angles ($37 + 54 = 91$) as if they open in opposite directions. The value $143^\\circ$ results from computing $180 - 37 = 143$, finding the supplement of the alternate interior angle rather than the difference between the two transversal angles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AIF94U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization conducts two independent random surveys of likely voters in a state. Survey P samples $500$ voters and finds $46\\%$ support a ballot measure, with a margin of error of $\\pm 4.5$ percentage points. Survey Q samples $2{,}000$ voters and finds $51\\%$ support the measure, with a margin of error of $\\pm 2.2$ percentage points. A journalist claims that these surveys prove the measure''s support is increasing. Which of the following best evaluates this claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is valid because Survey Q has a larger sample and therefore more accurate results."},{"key":"B","text":"The claim is invalid because the confidence intervals from the two surveys overlap, so the apparent difference could be due to sampling variability."},{"key":"C","text":"The claim is valid because $51\\%$ is greater than $46\\%$."},{"key":"D","text":"The claim is invalid because both surveys should have the same margin of error if they sample from the same population."}]$lyceon_json$::jsonb, 'B', NULL, E'Survey P''s confidence interval is $41.5\\%$ to $50.5\\%$, and Survey Q''s interval is $48.8\\%$ to $53.2\\%$. These intervals overlap (from $48.8\\%$ to $50.5\\%$), meaning the observed difference between the two point estimates could be due to sampling variability rather than a true change in support. Without additional evidence, the journalist''s claim is not supported. The claim that Survey Q is more accurate because of its larger sample conflates a narrower margin of error with proof that support changed over time. The claim based solely on $51\\%$ being greater than $46\\%$ ignores the uncertainty captured by the margins of error. The claim that both surveys should have the same margin of error misunderstands that margin of error depends on sample size, so different-sized samples naturally produce different margins.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AQ59N5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A rectangular garden has a length of $23$ feet and a width of $17$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '391', ARRAY['391'], E'The correct answer is $391$. The area of a rectangle is length times width: $23 \\times 17 = 391$ square feet. A common error is computing $23 + 17 = 40$ and then doubling to get the perimeter ($80$) instead of multiplying for area. Another error is miscalculating the product, for example obtaining $23 \\times 17 = 381$ through an arithmetic slip.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DB586X', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$7x + 2y = 31$$ $$3x - 2y = 9$$ What is the value of $x$ in the solution to the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Adding the two equations eliminates $y$: $(7x + 2y) + (3x - 2y) = 31 + 9$, which gives $10x = 40$, so $x = 4$. This can be verified by substituting back: $7(4) + 2y = 31$ gives $2y = 3$, so $y = \\frac{3}{2}$; checking the second equation, $3(4) - 2(\\frac{3}{2}) = 12 - 3 = 9$, which confirms the solution.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DZZBGZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A fuel blend is made by mixing biodiesel and petroleum diesel in a volume ratio of $7:9$. Biodiesel costs $4.30$ dollars per gallon and petroleum diesel costs $3.70$ dollars per gallon. What is the cost, in dollars, per gallon of the blended fuel? (Round to the nearest cent.)', NULL, $lyceon_json$[{"key":"A","text":"$3.93$"},{"key":"B","text":"$3.96$"},{"key":"C","text":"$4.00$"},{"key":"D","text":"$4.04$"}]$lyceon_json$::jsonb, 'B', NULL, E'In $16$ total gallons of blend ($7 + 9$), the cost is $7 \\times 4.30 + 9 \\times 3.70 = 30.10 + 33.30 = 63.40$ dollars. The cost per gallon is $\\frac{63.40}{16} = 3.9625$, which rounds to $3.96$. The value $3.93$ results from a computational slip such as miscomputing $7 \\times 4.30$ as $29.10$ instead of $30.10$, leading to $\\frac{62.40}{16} = 3.90$ and then rounding incorrectly. The value $4.00$ comes from taking the simple average $\\frac{4.30 + 3.70}{2} = 4.00$, which ignores the unequal mixing volumes. The value $4.04$ results from reversing the ratio components, assigning $9$ parts to biodiesel and $7$ parts to petroleum diesel: $\\frac{9(4.30) + 7(3.70)}{16} = \\frac{38.70 + 25.90}{16} = \\frac{64.60}{16} = 4.0375 \\approx 4.04$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EALMXB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'The population of a town was $8{,}500$ at the beginning of $2021$. The population increased by $8\\%$ from $2021$ to $2022$ and then decreased by $5\\%$ from $2022$ to $2023$. What was the population at the beginning of $2023$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8721', ARRAY['8721'], E'After an $8\\%$ increase, the population at the beginning of $2022$ is $8{,}500 \\times 1.08 = 9{,}180$. After a $5\\%$ decrease, the population at the beginning of $2023$ is $9{,}180 \\times 0.95 = 8{,}721$. A common error is to assume the net change is simply $+3\\%$, giving $8{,}500 \\times 1.03 = 8{,}755$, which ignores that the $5\\%$ decrease applies to the larger post-increase population. Another error is to apply both percentages to the original population: $8{,}500 + 0.08(8{,}500) - 0.05(8{,}500) = 8{,}500 + 680 - 425 = 8{,}755$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EJK5CS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle in the $xy$-plane passes through the points $(3, 11)$, $(3, -5)$, and $(11, 7)$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{53}$"},{"key":"B","text":"$8$"},{"key":"C","text":"$\\sqrt{65}$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $\\sqrt{65}$. The points $(3, 11)$ and $(3, -5)$ share the same $x$-coordinate, so the perpendicular bisector of the chord connecting them is horizontal: $y = \\frac{11 + (-5)}{2} = 3$. Thus the $y$-coordinate of the center is $k = 3$. Using the point $(3, 11)$: $(3 - h)^2 + (11 - 3)^2 = r^2$, giving $(3 - h)^2 + 64 = r^2$. Using the point $(11, 7)$: $(11 - h)^2 + (7 - 3)^2 = r^2$, giving $(11 - h)^2 + 16 = r^2$. Setting equal: $(3 - h)^2 + 64 = (11 - h)^2 + 16$. Expanding: $9 - 6h + h^2 + 64 = 121 - 22h + h^2 + 16$. Simplifying: $73 - 6h = 137 - 22h$, so $16h = 64$ and $h = 4$. Then $r^2 = (3 - 4)^2 + 64 = 1 + 64 = 65$, so $r = \\sqrt{65}$. The value $\\sqrt{53}$ results from an arithmetic slip when computing $r^2$, such as misidentifying the center. The value $8$ comes from halving the vertical distance between $(3, -5)$ and $(3, 11)$, which is the semi-chord length, not the radius. The value $9$ results from assuming the center lies on $x = 3$ and using $\\frac{11-(-5)}{2} + 1 = 9$ without properly finding the center.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FVMQGH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A school cafeteria tracks meal choices for $240$ students. Each student selects exactly one entree: pasta, salad, or soup. Of the $240$ students, $98$ are freshmen and $142$ are upperclassmen. Among freshmen, $37$ chose pasta, $41$ chose salad, and $20$ chose soup. Among upperclassmen, $58$ chose pasta, $49$ chose salad, and $35$ chose soup. If a student is selected at random from those who chose salad, what is the probability that the student is an upperclassman?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{49}{142}$"},{"key":"B","text":"$\\frac{49}{90}$"},{"key":"C","text":"$\\frac{49}{240}$"},{"key":"D","text":"$\\frac{41}{90}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of students who chose salad is $41 + 49 = 90$. The conditional probability that a salad-chooser is an upperclassman is $\\frac{49}{90}$. The value $\\frac{49}{142}$ uses the total number of upperclassmen as the denominator instead of conditioning on salad selection. The value $\\frac{49}{240}$ uses the entire student population as the denominator, ignoring the condition that the student chose salad. The value $\\frac{41}{90}$ gives the probability that a salad-chooser is a freshman, which is the reverse of what was asked.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GKI5RE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The mean of five numbers is $17$. Four of the numbers are $11$, $14$, $19$, and $23$. What is the fifth number?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'The sum of all five numbers must be $5 \\times 17 = 85$. The sum of the four known numbers is $11 + 14 + 19 + 23 = 67$. The fifth number is $85 - 67 = 18$. A common error is to compute the mean of the four known numbers ($\\frac{67}{4} = 16.75$) and subtract from $17$, giving $0.25$, which confuses the difference in means with the missing value. Another error is to divide $85$ by $4$ instead of subtracting, giving $21.25$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GPT90W', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 13x + 42}{x^2 - 36} \\cdot \\frac{x + 6}{x - 3}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 7}{x - 3}$"},{"key":"B","text":"$\\frac{x + 7}{x + 3}$"},{"key":"C","text":"$\\frac{x - 7}{x + 6}$"},{"key":"D","text":"$\\frac{x - 6}{x - 3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor each polynomial: $x^2 - 13x + 42 = (x - 6)(x - 7)$ and $x^2 - 36 = (x - 6)(x + 6)$. The expression becomes $\\frac{(x - 6)(x - 7)}{(x - 6)(x + 6)} \\cdot \\frac{x + 6}{x - 3}$. Cancel $(x - 6)$ in the first fraction, then cancel $(x + 6)$ between the denominator of the first fraction and the numerator of the second, yielding $\\frac{x - 7}{x - 3}$. The distractor $\\frac{x + 7}{x + 3}$ results from sign errors in the factoring, flipping the signs in both binomials. The distractor $\\frac{x - 7}{x + 6}$ comes from cancelling only $(x - 6)$ and not proceeding to multiply by $\\frac{x + 6}{x - 3}$. The distractor $\\frac{x - 6}{x - 3}$ reflects incorrectly cancelling $(x - 7)$ with $(x - 6)$ and retaining the wrong factor from the numerator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GU1F8U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'A line of best fit for a data set is given by $y = 3.1x + 8.7$. What is the predicted value of $y$ when $x = 7$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30.4', ARRAY['152/5', '30.4'], E'Substituting $x = 7$ into the equation gives $y = 3.1(7) + 8.7 = 21.7 + 8.7 = 30.4$. A common error is to omit the $y$-intercept, giving only $21.7$. Another error is to add $3.1 + 7 + 8.7 = 18.8$, treating all terms as additive rather than multiplying the slope by $x$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GWGLS3', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following is the solution to the inequality $9x - 31 \\geq 41$ ?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 8$"},{"key":"B","text":"$x \\geq 72$"},{"key":"C","text":"$x \\leq 8$"},{"key":"D","text":"$x \\geq \\frac{10}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $31$ to both sides of $9x - 31 \\geq 41$ gives $9x \\geq 72$. Dividing both sides by $9$ yields $x \\geq 8$. The result $x \\geq 72$ comes from stopping at $9x \\geq 72$ and omitting the division by $9$, returning the intermediate value. The inequality $x \\leq 8$ reverses the direction of the inequality sign, reflecting a misunderstanding that dividing by a positive number flips the inequality. The result $x \\geq \\frac{10}{9}$ comes from subtracting $31$ from $41$ to get $10$ rather than adding $31$ to $41$, then dividing $10$ by $9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H3Y4VZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A triangular prism has a base that is a right triangle with legs of length $9$ cm and $40$ cm. The prism has a length of $11$ cm. What is the volume of the prism, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$1980$"},{"key":"B","text":"$3960$"},{"key":"C","text":"$1800$"},{"key":"D","text":"$4510$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $1980$. The base is a right triangle with legs $9$ and $40$, so its area is $\\frac{1}{2}(9)(40) = 180$ square centimeters. The volume of the prism is the base area times the length: $180 \\times 11 = 1980$. The value $3960$ results from omitting the factor of $\\frac{1}{2}$ in the triangle area, computing $(9)(40)(11) = 3960$. The value $1800$ comes from an arithmetic slip such as multiplying $180 \\times 10$ instead of $180 \\times 11$. The value $4510$ results from incorrectly using the hypotenuse $\\sqrt{81 + 1600} = 41$ in place of one of the legs, computing $\\frac{1}{2}(41)(20)(11) = 4510$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HQF8D9', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'In the equation $6x + 7y = 83$, if $y = 5$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Substituting $y = 5$ into the equation gives $6x + 7(5) = 83$, which simplifies to $6x + 35 = 83$. Subtracting $35$ from both sides yields $6x = 48$, and dividing by $6$ gives $x = 8$. A common error is a sign mistake when isolating $x$, such as adding $35$ instead of subtracting it, or forgetting to divide $48$ by $6$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JA8BUF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'From the top of a $43$-meter-tall building, the angle of depression to a point on the ground is $31^\\circ$. From the same point on the ground, the angle of elevation to the top of a nearby flagpole (standing at ground level next to the building) is $12^\\circ$. What is the height of the flagpole, in meters, rounded to the nearest whole number? (Use $\\tan 31^\\circ \\approx 0.6009$ and $\\tan 12^\\circ \\approx 0.2126$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'The correct answer is $15$. The angle of depression from the top of the building to the ground point is $31^\\circ$, so the horizontal distance from the building to the point is $\\frac{43}{\\tan 31^\\circ} = \\frac{43}{0.6009} \\approx 71.56$ meters. The flagpole stands at the base of the building. From the ground point, the angle of elevation to the top of the flagpole is $12^\\circ$. The height of the flagpole is $71.56 \\times \\tan 12^\\circ = 71.56 \\times 0.2126 \\approx 15.21$, which rounds to $15$ meters. A common error is using $\\tan 31^\\circ$ as the multiplier rather than the divisor when computing the horizontal distance, yielding a much smaller distance. Another error is subtracting the flagpole height from $43$ instead of computing them independently.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JW6W2A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'A community center offers three weekend workshops: pottery, photography, and coding. Of $54$ members, $23$ enrolled in pottery, $18$ in photography, and $13$ in coding. Each member enrolls in exactly one workshop. Of the pottery members, $8$ have attended the center for more than $2$ years. Of the photography members, $11$ have attended for more than $2$ years. Of the coding members, $4$ have attended for more than $2$ years. Two members are selected at random without replacement from those who have attended for $2$ years or fewer. What is the probability that both selected members are from the photography workshop? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/155', ARRAY['7/155', '0.045', '.045'], E'The total number of seniors (attended more than $2$ years) is $8 + 11 + 4 = 23$, so there are $54 - 23 = 31$ members who have attended for $2$ years or fewer. The number of photography members who have attended for $2$ years or fewer is $18 - 11 = 7$. The probability that the first selected member is from photography is $\\frac{7}{31}$. Given that the first was from photography, there are $6$ photography members left out of $30$ remaining, so the probability for the second is $\\frac{6}{30}$. Multiplying gives $\\frac{7}{31} \\times \\frac{6}{30} = \\frac{42}{930} = \\frac{7}{155}$. A common error is to compute $\\frac{7}{31} \\times \\frac{7}{31} = \\frac{49}{961}$, which incorrectly treats the draws as with replacement. Another error is to use $\\frac{18}{54} \\times \\frac{17}{53}$, which fails to restrict to the subset who have attended for $2$ years or fewer.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K3CPUX', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A bakery produces muffins and scones. Each muffin requires $2$ hours of oven time and $5$ ounces of batter. Each scone requires $3$ hours of oven time and $4$ ounces of batter. The bakery has at most $37$ hours of oven time and at most $46$ ounces of batter available per day. If the bakery produces $8$ scones in a day, what is the maximum number of whole muffins it can produce that same day?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$2$"},{"key":"C","text":"$6$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $m$ be the number of muffins. The oven-time constraint is $2m + 3(8) \\leq 37$, which simplifies to $2m + 24 \\leq 37$, giving $2m \\leq 13$, so $m \\leq 6.5$. The batter constraint is $5m + 4(8) \\leq 46$, which simplifies to $5m + 32 \\leq 46$, giving $5m \\leq 14$, so $m \\leq 2.8$. Since both constraints must hold simultaneously and $m$ must be a whole number, the maximum is $2$. The value $3$ results from rounding $2.8$ up instead of down, an error in applying the integer constraint. The value $6$ comes from checking only the oven-time constraint and ignoring the batter constraint entirely. The value $4$ comes from incorrectly computing $5m + 32 \\leq 46$ as $5m \\leq 20$, mishandling the subtraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KK3L4F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A nutritionist randomly selects $260$ adults from a city''s population and records each participant''s daily fruit intake and blood pressure. The nutritionist finds that adults who consume more than $4$ servings of fruit per day have lower average blood pressure than those who consume fewer than $2$ servings per day. Which of the following conclusions is best supported by this study design?', NULL, $lyceon_json$[{"key":"A","text":"Eating more fruit causes lower blood pressure among adults in this city."},{"key":"B","text":"Eating more fruit causes lower blood pressure among all adults."},{"key":"C","text":"There is an association between daily fruit intake and blood pressure among adults in this city."},{"key":"D","text":"There is an association between daily fruit intake and blood pressure among all adults."}]$lyceon_json$::jsonb, 'C', NULL, E'Because participants were not randomly assigned to different levels of fruit intake, this observational study can only establish an association, not a causal relationship. Additionally, the random sample was drawn from a single city''s population, so the findings generalize to that city but not to all adults. The claim that fruit causes lower blood pressure in this city incorrectly infers causation from an observational design without random assignment to treatment groups. The claim that fruit causes lower blood pressure among all adults both infers causation and overgeneralizes beyond the sampled population. The claim of association among all adults correctly avoids causal language but extends the finding beyond the city from which the sample was drawn.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LG7KBK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A ladder leans against a wall, making an angle of $67^\\circ$ with the ground. The base of the ladder is $4.7$ meters from the wall. Which expression gives the length of the ladder, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{4.7}{\\cos 67^\\circ}$"},{"key":"B","text":"$\\frac{4.7}{\\sin 67^\\circ}$"},{"key":"C","text":"$4.7 \\cdot \\cos 67^\\circ$"},{"key":"D","text":"$4.7 \\cdot \\tan 67^\\circ$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{4.7}{\\cos 67^\\circ}$. The distance from the wall to the base of the ladder ($4.7$ m) is the side adjacent to the $67^\\circ$ angle, and the ladder is the hypotenuse. Since $\\cos 67^\\circ = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{4.7}{L}$, solving for $L$ gives $L = \\frac{4.7}{\\cos 67^\\circ}$. The expression $\\frac{4.7}{\\sin 67^\\circ}$ incorrectly treats the base distance as the side opposite the angle. The expression $4.7 \\cdot \\cos 67^\\circ$ inverts the relationship, computing the adjacent side from a hypotenuse of $4.7$ rather than solving for the hypotenuse. The expression $4.7 \\cdot \\tan 67^\\circ$ computes the wall height, not the ladder length.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LTH57W', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ is defined by the equation $4x - 3y = 21$. Line $n$ is parallel to line $m$ and passes through the point $(6, -1)$. What is the $y$-intercept of line $n$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting line $m$ in slope-intercept form gives $y = \\frac{4}{3}x - 7$, so the slope of line $m$ is $\\frac{4}{3}$. Since line $n$ is parallel to line $m$, it has the same slope. Using point-slope form with $(6, -1)$: $y - (-1) = \\frac{4}{3}(x - 6)$, which simplifies to $y + 1 = \\frac{4}{3}x - 8$, so $y = \\frac{4}{3}x - 9$. The $y$-intercept is $-9$. The value $-7$ comes from using the $y$-intercept of line $m$ itself, rather than computing the $y$-intercept of the parallel line through the given point. The value $-1$ comes from misreading the question and reporting the $y$-coordinate of the given point instead of computing the $y$-intercept. The value $9$ results from a sign error in the final calculation, dropping the negative from $-9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MGPYIR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone has a base radius of $21$ cm and a height of $28$ cm. A plane parallel to the base cuts the cone at a height of $14$ cm from the base, splitting it into a smaller cone (the top portion) and a frustum (the bottom portion). What is the volume of the frustum, in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$3087\\pi$"},{"key":"B","text":"$4116\\pi$"},{"key":"C","text":"$3601.5\\pi$"},{"key":"D","text":"$1029\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $3601.5\\pi$. The full cone has base radius $21$, height $28$, and volume $\\frac{1}{3}\\pi(21^2)(28) = \\frac{1}{3}\\pi(441)(28) = 4116\\pi$. The cut is at height $14$ from the base, so the small cone (top portion) extends from height $14$ to the apex at height $28$, giving it a height of $14$. By similar triangles, the small cone''s radius is $21 \\times \\frac{14}{28} = \\frac{21}{2} = 10.5$. The small cone volume is $\\frac{1}{3}\\pi(10.5^2)(14) = \\frac{1}{3}\\pi(110.25)(14) = \\frac{1543.5\\pi}{3} = 514.5\\pi$. The frustum volume is $4116\\pi - 514.5\\pi = 3601.5\\pi$. The value $3087\\pi$ results from using only $\\frac{3}{4}$ of the full volume (since the cut is at half-height), incorrectly assuming volume scales linearly with height. The value $4116\\pi$ is the volume of the entire cone, not the frustum alone. The value $1029\\pi$ comes from computing $\\frac{1}{4}$ of the full cone volume ($\\frac{4116\\pi}{4}$), incorrectly assuming the small cone is half the volume because the cut is at half the height.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MOX7PP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $19$ and the hypotenuse has length $181$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$162$"},{"key":"B","text":"$170$"},{"key":"C","text":"$180$"},{"key":"D","text":"$\\sqrt{33122}$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Pythagorean theorem, $a^2 + b^2 = c^2$, so the other leg is $\\sqrt{181^2 - 19^2} = \\sqrt{32761 - 361} = \\sqrt{32400} = 180$. The value $162$ results from subtracting the lengths directly ($181 - 19 = 162$) instead of using the Pythagorean theorem. The value $170$ results from an arithmetic slip when computing $\\sqrt{32400}$, possibly from a rounding or calculator error. The value $\\sqrt{33122}$ results from adding $181^2 + 19^2$ instead of subtracting, applying the formula as though the given leg were the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N7R1G0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'The function $f$ is defined by $f(x) = 17x - 59$. What is the value of $f(7)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Substituting $x = 7$ gives $f(7) = 17(7) - 59 = 119 - 59 = 60$. A common error is adding $59$ instead of subtracting, which would give $178$, or computing $17 + 7 = 24$ instead of $17 \\times 7 = 119$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NECKD4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a circumference of $38\\pi$ inches. What is the radius of the circle, in inches?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$19$"},{"key":"C","text":"$38$"},{"key":"D","text":"$361$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $19$. The circumference formula is $C = 2\\pi r$. Setting $2\\pi r = 38\\pi$ and dividing both sides by $2\\pi$ gives $r = 19$. The value $12$ results from an arithmetic slip in dividing $38$ by $2$. The value $38$ comes from confusing the diameter with the radius, stopping at $2r = 38$ without dividing by $2$. The value $361$ results from squaring $19$, confusing the radius computation with the area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OH9ISY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sells a textbook for $68$ dollars after applying a $15\\%$ discount to the original price. What is the original price, in dollars, of the textbook?', NULL, $lyceon_json$[{"key":"A","text":"$57.80$"},{"key":"B","text":"$73.10$"},{"key":"C","text":"$78.20$"},{"key":"D","text":"$80$"}]$lyceon_json$::jsonb, 'D', NULL, E'After a $15\\%$ discount, the sale price is $85\\%$ of the original. Let $p$ be the original price: $0.85p = 68$, so $p = \\frac{68}{0.85} = 80$ dollars. The value $57.80$ results from subtracting $15\\%$ of $68$ from $68$: $68 - 0.15(68) = 68 - 10.20 = 57.80$, which applies the discount to the sale price instead of finding the original. The value $73.10$ comes from an arithmetic error when dividing, such as computing $\\frac{68}{0.93}$ instead of $\\frac{68}{0.85}$. The value $78.20$ results from adding $15\\%$ of $68$ to $68$: $68 + 10.20 = 78.20$, which uses the wrong base for the percentage calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OOSAEV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A clothing store marks up the wholesale cost of a shirt by $40\\%$ to set the retail price. During a sale, the store discounts the retail price by $25\\%$. If the store''s profit on each shirt sold during the sale is $2.10$ dollars, what is the wholesale cost of the shirt, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$29.40$"},{"key":"C","text":"$42$"},{"key":"D","text":"$58.80$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $w$ be the wholesale cost. The retail price is $1.40w$. After a $25\\%$ discount, the sale price is $0.75 \\times 1.40w = 1.05w$. The profit per shirt is $1.05w - w = 0.05w$. Setting $0.05w = 2.10$ gives $w = \\frac{2.10}{0.05} = 42$ dollars. The value $14$ results from dividing $2.10$ by $0.15$ (incorrectly treating the net effect as $40\\% - 25\\% = 15\\%$), giving $14$. The value $29.40$ comes from dividing $2.10$ by $0.40 \\times 0.25 = 0.10$, giving $21$, then multiplying by $1.40$, confusing the markup and discount operations. The value $58.80$ results from computing $42 \\times 1.40 = 58.80$, which is the retail price rather than the wholesale cost.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P7DYW3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A biologist recorded the average daily temperature in degrees Fahrenheit, $x$, and the number of chirps per minute produced by a cricket species, $y$. The line of best fit is $y = 3.4x - 148$. Which of the following is the best interpretation of the $y$-intercept in this context?', NULL, $lyceon_json$[{"key":"A","text":"When the temperature is $0$ degrees Fahrenheit, the predicted number of chirps per minute is $-148$."},{"key":"B","text":"For each increase of $1$ degree Fahrenheit, the predicted number of chirps per minute increases by $148$."},{"key":"C","text":"The $y$-intercept has no meaningful interpretation in this context because a negative number of chirps is not possible."},{"key":"D","text":"For each additional chirp per minute, the temperature increases by $148$ degrees Fahrenheit."}]$lyceon_json$::jsonb, 'C', NULL, E'The $y$-intercept $-148$ is the predicted value of $y$ when $x = 0$, meaning at $0$ degrees Fahrenheit. Since a cricket cannot produce a negative number of chirps, this value has no meaningful real-world interpretation — the model is only valid within the range of temperatures studied. Stating that the predicted chirps at $0$ degrees is $-148$ is mathematically literal but not a meaningful interpretation in context, because negative chirps are impossible. The claim that chirps increase by $148$ per degree confuses the $y$-intercept ($-148$) with the slope ($3.4$). The claim that temperature increases by $148$ degrees per chirp reverses the roles of the variables and confuses the intercept with the slope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PIEHIF', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the slope of the line that passes through the points $(-2, 19)$ and $(9, -3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$-\\frac{1}{2}$"},{"key":"C","text":"$\\frac{1}{2}$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope formula gives $m = \\frac{-3 - 19}{9 - (-2)} = \\frac{-22}{11} = -2$. The value $-\\frac{1}{2}$ results from inverting the slope formula, computing the change in $x$ over the change in $y$ (run over rise) instead of rise over run. The value $\\frac{1}{2}$ compounds that inversion error with a sign error, losing the negative sign from the numerator. The value $2$ results from dropping the negative sign from the correct calculation of $\\frac{-22}{11}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PWBY8K', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$kx + 8y = 23$$ $$6x + 12y = 31$$ In the system of equations above, $k$ is a constant. If the system has no solution, what is the value of $k$ ?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$9$"},{"key":"C","text":"$-4$"},{"key":"D","text":"$\\frac{2}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system of two linear equations has no solution when the lines are parallel: the ratios of the coefficients of $x$ and $y$ are equal, but the ratio of the constants is different. Setting $\\frac{k}{6} = \\frac{8}{12}$ gives $\\frac{k}{6} = \\frac{2}{3}$, so $k = 4$. Checking the constants: $\\frac{23}{31} \\neq \\frac{2}{3}$ (since $\\frac{2}{3} \\approx 0.667$ while $\\frac{23}{31} \\approx 0.742$), confirming the system has no solution when $k = 4$. The value $9$ results from incorrectly setting $\\frac{k}{6} = \\frac{12}{8}$, reversing the ratio of the $y$-coefficients. The value $-4$ introduces an erroneous negative sign when solving $\\frac{k}{6} = \\frac{2}{3}$ for $k$. The value $\\frac{2}{3}$ is the simplified ratio $\\frac{8}{12}$ itself rather than the result of solving $\\frac{k}{6} = \\frac{2}{3}$ for $k$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QZ20G4', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A gym membership has a monthly fee and a per-class charge. In a month where a member attends 11 classes, the total cost is 139 dollars. In a month where the member attends 19 classes, the total cost is 203 dollars. The gym then increases the monthly fee by 12 dollars and decreases the per-class charge by 1 dollar. Under the new pricing, what is the total cost, in dollars, for a month with 15 classes?', NULL, $lyceon_json$[{"key":"A","text":"$156$"},{"key":"B","text":"$168$"},{"key":"C","text":"$171$"},{"key":"D","text":"$183$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $c$ be the per-class charge and $m$ be the monthly fee. From the given information, $11c + m = 139$ and $19c + m = 203$. Subtracting the first equation from the second gives $8c = 64$, so $c = 8$. Substituting back yields $m = 139 - 11(8) = 139 - 88 = 51$. The new per-class charge is $8 - 1 = 7$ dollars and the new monthly fee is $51 + 12 = 63$ dollars. For 15 classes under new pricing: $7(15) + 63 = 105 + 63 = 168$ dollars. The value $156$ results from applying only the per-class decrease while keeping the original monthly fee: $7(15) + 51 = 156$. The value $171$ results from using the original pricing without any adjustments: $8(15) + 51 = 171$. The value $183$ results from applying only the monthly fee increase while keeping the original per-class charge: $8(15) + 63 = 183$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 115, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SAK0P9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tests a new sleep aid by recruiting $210$ adults from seven clinics ($30$ per clinic). At each clinic, $15$ participants are randomly assigned to receive the sleep aid and $15$ receive a placebo. After $6$ weeks, participants taking the sleep aid report an average of $47$ more minutes of sleep per night than the placebo group, and this difference is statistically significant. However, all seven clinics are located in temperate coastal cities. Which of the following statements best describes a limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"Because participants were not randomly assigned to groups, the study cannot establish that the sleep aid caused the increase in sleep."},{"key":"B","text":"A sample size of $210$ is insufficient to detect a meaningful difference in sleep duration."},{"key":"C","text":"The results may not generalize to adults in substantially different climatic or geographic settings because all clinics were in similar environments."},{"key":"D","text":"The $6$-week treatment period is too brief for a sleep aid to produce any measurable effect."}]$lyceon_json$::jsonb, 'C', NULL, E'The study uses random assignment within each clinic, so it can establish a causal effect for the population represented by the clinics. However, since all seven clinics are in temperate coastal cities, the results may not generalize to adults living in different climatic or geographic settings, where factors like altitude, temperature extremes, or lifestyle differences could interact with the sleep aid''s effectiveness. The claim that participants were not randomly assigned is incorrect, as $15$ participants at each clinic were randomly assigned to the sleep aid and $15$ to the placebo. The claim that $210$ participants is too small ignores that the study already found a statistically significant difference, indicating sufficient power for the observed effect. The claim that $6$ weeks is too brief is an unsupported assertion that contradicts the study''s own statistically significant finding of $47$ additional minutes of sleep per night.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TCEWRP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 3x^2 - 24x + 53$. The function $g$ is defined by $g(x) = f(x + 2) - 9$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-9$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, rewrite $f(x)$ in vertex form by completing the square: $f(x) = 3(x^2 - 8x) + 53 = 3(x^2 - 8x + 16 - 16) + 53 = 3(x - 4)^2 - 48 + 53 = 3(x - 4)^2 + 5$. The minimum value of $f$ is $5$. Now, $g(x) = f(x + 2) - 9 = 3((x + 2) - 4)^2 + 5 - 9 = 3(x - 2)^2 - 4$. Since $(x - 2)^2 \\geq 0$, the minimum of $g$ is $-4$, occurring at $x = 2$. The distractor $5$ comes from finding the minimum of $f$ without applying the vertical shift of $-9$. The distractor $-9$ results from assuming the minimum of $f$ is $0$ and only applying the $-9$ shift. The distractor $4$ results from a sign error, computing $-5 + 9 = 4$ instead of $5 - 9 = -4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TCMRK5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A wildlife sanctuary houses $11$ birds for every $4$ reptiles. If the sanctuary currently has $44$ reptiles, how many birds does it house?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$44$"},{"key":"C","text":"$121$"},{"key":"D","text":"$484$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of birds to reptiles is $11:4$. Since there are $44$ reptiles, the scale factor is $\\frac{44}{4} = 11$. The number of birds is $11 \\times 11 = 121$. The value $16$ results from dividing $44 \\div 11 \\times 4 = 16$, which inverts the ratio and finds reptiles per group of birds. The value $44$ mistakes the number of reptiles for the number of birds, ignoring the ratio entirely. The value $484$ comes from multiplying $44 \\times 11 = 484$ without recognizing that $11$ is the birds-per-group count and should be scaled by the factor, not multiplied by the total reptile count directly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UDRSCG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The number of books read last month by each of $9$ students in a reading club is listed below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UR3U86', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 - 3x - 10$ and $y = 2x + 11$ intersect at two points. What is the sum of the $x$-coordinates of these two intersection points?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$3$"},{"key":"C","text":"$21$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set the two expressions equal: $x^2 - 3x - 10 = 2x + 11$, which simplifies to $x^2 - 5x - 21 = 0$. By Vieta''s formulas, the sum of the roots of $x^2 - 5x - 21 = 0$ equals $5$, the negation of the coefficient of $x$ when the leading coefficient is $1$. The distractor $3$ results from only partially rearranging the equation, reading $-3$ from the original quadratic coefficient instead of the rearranged $-5$. The distractor $21$ comes from confusing the sum of roots with the constant term of the rearranged equation. The distractor $-5$ results from a sign error, forgetting to negate the coefficient of $x$ when applying Vieta''s formulas.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WAUWX7', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $7(2x^2 - 5x + 3) - 4(3x^2 + 2x - 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 - 43x + 57$"},{"key":"B","text":"$26x^2 - 43x + 57$"},{"key":"C","text":"$2x^2 - 27x - 15$"},{"key":"D","text":"$2x^2 - 43x - 15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the first term gives $14x^2 - 35x + 21$. Distributing the second term gives $-12x^2 - 8x + 36$. Combining like terms: $(14 - 12)x^2 = 2x^2$, $(-35 - 8)x = -43x$, and $21 + 36 = 57$. The result is $2x^2 - 43x + 57$. The distractor $26x^2 - 43x + 57$ results from adding the $x^2$ coefficients as $14 + 12 = 26$ instead of subtracting. The distractor $2x^2 - 27x - 15$ results from sign errors when distributing $-4$: treating $-4(2x)$ as $+8x$ instead of $-8x$, giving $-35 + 8 = -27$, and computing $21 - 36 = -15$ instead of $21 + 36 = 57$. The distractor $2x^2 - 43x - 15$ gets the $x$ term correct but makes a sign error on the constant, computing $21 - 36 = -15$ instead of $21 + 36 = 57$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WB9LYD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $220$ households in a county found that $43\\%$ have at least one pet, with a margin of error of $6$ percentage points. Which of the following is a valid interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $43\\%$ of all households in the county have at least one pet."},{"key":"B","text":"If the survey were repeated, exactly $43\\%$ of households would again report having a pet."},{"key":"C","text":"It is plausible that between $37\\%$ and $49\\%$ of all households in the county have at least one pet."},{"key":"D","text":"Between $37\\%$ and $49\\%$ of the $220$ sampled households have at least one pet."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $6$ percentage points means the plausible range for the true population proportion is $43\\% \\pm 6\\%$, or between $37\\%$ and $49\\%$. This interval describes where the population parameter plausibly lies, not the sample itself. The claim that exactly $43\\%$ of all households have a pet treats the sample statistic as the exact population value, ignoring sampling variability. The claim that a repeated survey would yield exactly $43\\%$ misunderstands that different random samples produce different estimates. The claim that the interval describes the sampled households confuses the sample, which was directly observed at exactly $43\\%$, with the population-level inference the margin of error is designed to address.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X2K1YG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $11$ yellow tokens, $7$ purple tokens, and $3$ white tokens. If one token is drawn at random, what is the probability of drawing a purple token?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{21}$"},{"key":"B","text":"$\\frac{7}{18}$"},{"key":"C","text":"$\\frac{7}{11}$"},{"key":"D","text":"$\\frac{1}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of tokens is $11 + 7 + 3 = 21$. The probability of drawing a purple token is $\\frac{7}{21}$, which simplifies to $\\frac{1}{3}$. The value $\\frac{7}{18}$ results from miscounting the total as $18$ by omitting the white tokens. The value $\\frac{7}{11}$ results from using only the yellow token count as the denominator rather than the total. The value $\\frac{1}{7}$ confuses the number of purple tokens with the total number of tokens.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X4XQ01', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h$ is defined by $h(x) = 3^{x-4} - 2$. Which of the following describes the range of $h$?', NULL, $lyceon_json$[{"key":"A","text":"All real numbers greater than $-2$"},{"key":"B","text":"All real numbers greater than or equal to $-2$"},{"key":"C","text":"All real numbers greater than $4$"},{"key":"D","text":"All real numbers"}]$lyceon_json$::jsonb, 'A', NULL, E'The base exponential $3^{x-4}$ is always positive for all real $x$, approaching $0$ as $x \\to -\\infty$ but never equaling $0$. Subtracting $2$ shifts the output down by $2$, so $h(x) > -2$ for all $x$, but $h(x)$ never equals $-2$. Therefore the range is all real numbers greater than $-2$. The choice stating greater than or equal to $-2$ incorrectly includes $-2$, which would require $3^{x-4} = 0$, an impossibility for exponential functions. The choice stating greater than $4$ confuses the horizontal shift parameter with the vertical asymptote. The choice stating all real numbers ignores that exponential functions with a positive base always produce positive outputs, making values at or below $-2$ unreachable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XGF0NM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $13$ values is arranged in increasing order. The minimum value is $8$, the maximum value is $52$, and the median is $29$. If the value $52$ is replaced by $67$, which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"Both the median and the range increase."},{"key":"B","text":"The median increases, but the range stays the same."},{"key":"C","text":"The range increases, but the median stays the same."},{"key":"D","text":"Both the median and the range stay the same."}]$lyceon_json$::jsonb, 'C', NULL, E'With $13$ values in increasing order, the median is the $7$th value. Replacing the maximum value ($52$, the $13$th value) with $67$ does not change any of the first $12$ values, so the $7$th value remains $29$ and the median is unchanged. The range changes from $52 - 8 = 44$ to $67 - 8 = 59$, so the range increases. The claim that both increase is wrong because the median is determined by the $7$th value, which is unaffected by changing the $13$th value. The claim that the median increases but the range stays the same gets both effects backward. The claim that both stay the same fails to recognize that the range depends on the maximum value, which did change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y2ZQC4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What value of $x$ satisfies the equation $$4(3x - 13) - 5(2x + 1) = x - 38\\;?$$', NULL, $lyceon_json$[{"key":"A","text":"$-20$"},{"key":"B","text":"$13$"},{"key":"C","text":"$14$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing gives $12x - 52 - 10x - 5 = x - 38$. Combining like terms on the left yields $2x - 57 = x - 38$. Subtracting $x$ from both sides and adding $57$ gives $x = 19$. The value $-20$ results from an arithmetic slip in distributing $4(3x - 13)$: computing $12x - 13$ instead of $12x - 52$ (failing to multiply $13$ by $4$), which leads to $2x - 18 = x - 38$ and $x = -20$. The value $13$ results from a sign error in distributing $-5(2x + 1)$, obtaining $-10x + 1$ instead of $-10x - 5$, which leads to $2x - 51 = x - 38$ and $x = 13$. The value $14$ results from dropping the constant term when distributing $-5(2x + 1)$, retaining only $-10x$ and omitting $-5$, which leads to $2x - 52 = x - 38$ and $x = 14$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y6NAGX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A packaging company charges a flat rate plus a per-item fee for shipping orders. Packaging 80 items costs 59 dollars, and packaging 200 items costs 107 dollars. Which function $f(n)$ gives the total cost, in dollars, of packaging $n$ items?', NULL, $lyceon_json$[{"key":"A","text":"$f(n) = 0.4n + 27$"},{"key":"B","text":"$f(n) = 0.4n + 59$"},{"key":"C","text":"$f(n) = 2.5n + 27$"},{"key":"D","text":"$f(n) = 0.4n - 27$"}]$lyceon_json$::jsonb, 'A', NULL, E'The per-item rate is $\\frac{107 - 59}{200 - 80} = \\frac{48}{120} = 0.4$ dollars per item. The flat rate is $59 - 0.4(80) = 59 - 32 = 27$ dollars. So $f(n) = 0.4n + 27$. The expression $0.4n + 59$ results from using the total cost for 80 items as the flat rate instead of computing the actual fixed charge. The expression $2.5n + 27$ results from inverting the rate calculation, dividing the change in items by the change in cost ($\\frac{120}{48} = 2.5$) instead of cost by items. The expression $0.4n - 27$ results from a sign error, subtracting the flat rate instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YC4TIV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In a triangle, two of the interior angles measure $34^\\circ$ and $89^\\circ$. What is the measure, in degrees, of the third interior angle?', NULL, $lyceon_json$[{"key":"A","text":"$47^\\circ$"},{"key":"B","text":"$57^\\circ$"},{"key":"C","text":"$67^\\circ$"},{"key":"D","text":"$123^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of interior angles in any triangle is $180^\\circ$. The third angle is $180 - 34 - 89 = 57$, so the correct answer is $57^\\circ$. The value $47^\\circ$ results from an arithmetic slip such as computing $34 + 89 = 133$ instead of $123$. The value $67^\\circ$ comes from miscalculating the subtraction, for example treating $180 - 123$ as $67$ instead of $57$. The value $123^\\circ$ results from misreading the question and reporting the sum of the two given angles rather than the missing third angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YM9TTU', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$2x + 5y = 41$$ $$3x - 2y = -5$$ What is the value of $x + y$ for the solution $(x, y)$ to the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$3$"},{"key":"C","text":"$10$"},{"key":"D","text":"$41$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying the first equation by $2$ gives $4x + 10y = 82$. Multiplying the second equation by $5$ gives $15x - 10y = -25$. Adding these eliminates $y$: $19x = 57$, so $x = 3$. Substituting into $2(3) + 5y = 41$ gives $5y = 35$, so $y = 7$. Therefore $x + y = 10$. The value $-4$ results from computing $x - y = 3 - 7$ instead of $x + y$, misreading what the problem asks. The value $3$ comes from finding $x$ but stopping before adding $y$, an incomplete solution. The value $41$ confuses the right-hand side of the first equation with the requested quantity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20Q8MD0', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief profile of the baobab tree for an environmental science newsletter. The student wants to highlight the baobab''s practical importance to local communities. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20VVGRO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The average lifespan of the seventeen species of baobab trees documented across the savannas of western Madagascar ______ considerably longer than botanists had assumed before carbon-dating studies were conducted in 2019.', $lyceon_json$[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"have been"},{"key":"D","text":"were being"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is the singular noun ''lifespan,'' not the plural nouns ''species'' or ''trees'' that appear in the intervening prepositional phrases. Because the subject is singular, the verb must also be singular. The sentence describes a present-tense fact about the average lifespan, so the simple present ''is'' is correct. The option ''are'' incorrectly uses a plural verb with the singular subject ''lifespan.'' The option ''have been'' pairs a plural auxiliary with a singular subject and shifts to the present perfect without contextual justification. The option ''were being'' introduces the past progressive passive, which is both plural and in the wrong tense for stating a general fact.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21607IE', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Cognitive scientist Yael Navon challenges the prevailing model of creative insight, which holds that breakthrough ideas emerge from unconscious incubation during periods of mental rest. Navon acknowledges that anecdotal accounts from artists and scientists often describe sudden flashes of inspiration following breaks from focused work, but she argues that these self-reports reflect a perceptual illusion: because the incremental cognitive steps leading to the breakthrough occurred below conscious awareness, the thinker perceives the final step—the moment the solution crosses the threshold of consciousness—as the entirety of the process. In controlled experiments, Navon demonstrated that subjects who reported sudden insight moments had, in fact, been making measurable progress toward the solution throughout the ostensible rest period, as evidenced by increasing accuracy in related tasks administered during breaks. Navon concludes that creative breakthroughs are the culmination of continuous, largely unconscious cognitive work, not the product of a qualitatively distinct incubation mechanism.', $lyceon_json$[{"key":"A","text":"Creative breakthroughs result from continuous unconscious processing rather than from a separate incubation mechanism, even though they are subjectively experienced as sudden."},{"key":"B","text":"Unconscious cognitive processes play no meaningful role in creative problem-solving."},{"key":"C","text":"Self-reports from artists and scientists about their creative processes are deliberately misleading."},{"key":"D","text":"Controlled experiments are inherently unsuitable for studying the nature of creative insight."}]$lyceon_json$::jsonb, 'A', NULL, E'Navon''s central claim is that creative breakthroughs emerge from continuous unconscious cognitive work that merely appears sudden when it crosses the threshold of awareness, rather than from a qualitatively distinct incubation mechanism. The choice describing continuous unconscious processing versus a separate incubation mechanism accurately captures this claim. The assertion that unconscious processes play no role misreads Navon''s argument; she explicitly identifies the processing as unconscious—her objection is to characterizing it as a distinct incubation mechanism rather than as ongoing cognitive work. The claim that self-reports are deliberately misleading distorts Navon''s position; she describes a perceptual illusion, not intentional deception. The suggestion that controlled experiments cannot study creative insight contradicts Navon''s own methodology, which relies on experimental evidence to support her argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW219PFCB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The Victorian architect Augustus Welby Pugin believed that the medieval Gothic style was not merely an aesthetic preference but a moral imperative, and he ______ the neoclassical buildings then fashionable in London as spiritually bankrupt imitations of pagan temples.', $lyceon_json$[{"key":"A","text":"denounced"},{"key":"B","text":"catalogued"},{"key":"C","text":"inaugurated"},{"key":"D","text":"arbitrated"}]$lyceon_json$::jsonb, 'A', NULL, E'Pugin viewed the Gothic style as a moral imperative and considered neoclassical buildings spiritually bankrupt imitations, indicating strong condemnation. The word meaning to publicly declare as wrong or evil captures this vehement criticism precisely. The word meaning to systematically list or classify describes a neutral organizing activity, which does not convey moral condemnation. The word meaning to formally begin or introduce suggests launching something new, not attacking an existing style. The word meaning to act as a neutral judge in a dispute implies impartiality, which contradicts Pugin''s passionate opposition to neoclassicism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21ER0C1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Before the acoustic engineers finished calibrating the concert hall''s new speaker array in the spring of 2023, the venue''s management ______ three separate performances because of persistent audio distortions that made vocal frequencies nearly unintelligible to audience members seated in the upper balcony.', $lyceon_json$[{"key":"A","text":"had canceled"},{"key":"B","text":"has canceled"},{"key":"C","text":"would cancel"},{"key":"D","text":"canceled"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction ''before [past event]'' establishes a temporal sequence requiring the past perfect tense in the main clause to indicate that one past action was completed prior to another past action. The cancellations were already complete before the engineers finished calibrating, so the past perfect ''had canceled'' is the correct form. The present perfect ''has canceled'' is inappropriate because the entire context is anchored in the past (''finished,'' ''spring of 2023''), and the present perfect connects a past event to the present moment. The conditional ''would cancel'' implies a hypothetical scenario rather than describing actual events. The simple past ''canceled'' fails to convey the completed-before sequence that the temporal clause with ''before'' establishes in this context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25949JV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the Cassini spacecraft''s seventeen-year mission to Saturn yielded thousands of detailed photographs of the planet''s ring ______ the data that most excited planetary scientists were the chemical readings from the plumes of Enceladus, which suggested conditions potentially hospitable to microbial life.', $lyceon_json$[{"key":"A","text":"system, the data"},{"key":"B","text":"system; the data"},{"key":"C","text":"system. The data"},{"key":"D","text":"system the data"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with a subordinate clause introduced by ''Although,'' which must be joined to the main clause by a comma. Since the subordinate clause (''Although the Cassini spacecraft''s... ring system'') is dependent and cannot stand alone, it cannot be separated from the main clause by a semicolon or period, both of which require independent clauses on each side. A semicolon after ''system'' would leave the ''Although'' clause as a fragment. A period would similarly isolate the dependent clause as a fragment. Omitting all punctuation creates a run-on that fuses the subordinate clause directly into the main clause without a required grammatical boundary, making the sentence difficult to parse.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25LHHZL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing an article about the ceramic traditions of the Pueblo peoples for an art history journal and wants to contrast the artistic philosophies underlying two distinct Pueblo pottery styles. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW267KV7U', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Kofi Adjei has found that the hawksbill sea turtle population along Ghana''s Cape Three Points coastline declined by 37 percent between 2014 and 2022. ______ the Ghanaian government introduced strict penalties for poaching sea turtles and allocated funding for nest-monitoring patrols in the region.', $lyceon_json$[{"key":"A","text":"In response,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Likewise,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence describes governmental action taken as a direct reaction to the population decline described in the first sentence. The transition "In response" correctly signals that the second sentence is a consequence of or reaction to the problem identified in the first. The option suggesting contrast ("On the other hand") implies an opposing perspective, but the second sentence is not contradicting the first — it describes action motivated by it. The option "For instance" implies the second sentence exemplifies the first, but government intervention is not an example of population decline. The option "Likewise" implies a parallel situation, but the government action is a reaction to the decline, not a similar phenomenon.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
