INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BKBFTU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The editorial board has recommended that every article submitted to the journal after September 1 ______ a structured data-availability statement specifying whether the underlying datasets can be accessed by independent researchers, a policy that several contributing authors have criticized as overly burdensome.', $lyceon_json$[{"key":"A","text":"includes"},{"key":"B","text":"include"},{"key":"C","text":"will include"},{"key":"D","text":"has included"}]$lyceon_json$::jsonb, 'B', NULL, E'The verb ''recommended'' triggers the mandative subjunctive in the ''that'' clause that follows it. In Standard English, verbs expressing demands, recommendations, or requirements—such as ''recommend,'' ''mandate,'' ''insist,'' and ''suggest''—take the subjunctive mood, which uses the bare infinitive (base form) of the verb regardless of the subject''s number. Although ''every article'' is grammatically singular and would ordinarily take the indicative ''includes,'' the subjunctive requires the uninflected base form ''include.'' The option ''will include'' incorrectly inserts a future-tense auxiliary into the subjunctive construction, which is not permitted in Standard English after verbs of recommendation. The option ''has included'' uses the present perfect indicative, which both violates the subjunctive requirement and implies past completion rather than a forward-looking policy.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CX3LUN', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historians have long credited the 1854 Broad Street cholera outbreak in London as the event that convinced public health authorities of the waterborne transmission theory. Recent archival work by epidemiologist Yuki Tanabe, however, reveals that municipal officials continued to fumigate streets and burn sulfur for nearly a decade after the outbreak, measures consistent with the miasma theory they supposedly abandoned. ______ Tanabe argues that the shift from miasma to germ theory in British public health policy was not a sudden conversion but a protracted, uneven transition shaped more by infrastructure budgets than by scientific persuasion.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"On this basis,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'B', NULL, E'The second sentence presents archival evidence that officials continued miasma-based practices long after they were supposedly abandoned. The third sentence draws a broader conclusion from that evidence: the transition was protracted and budget-driven, not sudden. The transition "On this basis" correctly signals that the third sentence builds an argument grounded in the evidence just presented. The option "Accordingly" might seem to work as a causal connector, but it implies the third sentence follows as a natural or expected consequence of the second, whereas Tanabe is making an interpretive argument from the evidence, not stating an inevitable outcome. The option "Nonetheless" implies the third sentence concedes or contrasts with the second, but the third sentence reinforces and extends the second sentence''s implications rather than qualifying them. The option "For example" implies the third sentence is an illustrative instance of the second, but the third sentence is a broader thesis drawn from the evidence, not a specific case exemplifying it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DVM581', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In the early twentieth century, pellagra devastated communities across the American South, killing thousands annually. Most physicians attributed the disease to an infectious agent or toxin. In 1914, epidemiologist Joseph Goldberger was dispatched by the U.S. Public Health Service to investigate. After observing that staff at institutions where pellagra was rampant never contracted the disease themselves, Goldberger hypothesized that pellagra resulted from nutritional deficiency rather than infection. He tested this by altering the diets of afflicted orphanage residents, eliminating pellagra entirely within months. Yet many Southern physicians and politicians resisted his findings for over a decade, partly because accepting a dietary cause implied uncomfortable truths about regional poverty.', $lyceon_json$[{"key":"A","text":"It chronicles a disease outbreak, presents an investigator's contrasting hypothesis and supporting experiment, and then accounts for resistance to the findings."},{"key":"B","text":"It compares two equally supported explanations for a disease and leaves the question of which is correct unresolved."},{"key":"C","text":"It describes a medical controversy and argues that political interference permanently prevented a scientific consensus from forming."},{"key":"D","text":"It evaluates the experimental methodology of a historical study and identifies flaws that weakened its conclusions."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves through distinct stages: it describes the pellagra crisis and the prevailing infectious-cause view, introduces Goldberger''s contrasting nutritional-deficiency hypothesis, presents his dietary experiment as evidence, and concludes by explaining why resistance persisted. This matches the option about chronicling a disease, presenting a contrasting hypothesis with experiment, and accounting for resistance. The option about two equally supported explanations misrepresents the text, which clearly favors Goldberger''s hypothesis through experimental results. The option about political interference permanently preventing consensus overstates the passage; it says resistance lasted over a decade, not that consensus was never reached. The option about evaluating methodology and identifying flaws mischaracterizes the passage entirely; it does not critique Goldberger''s methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EXOTQY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'After seven months of drought, the regional water authority declared that the reservoir had reached ______ levels, prompting mandatory rationing for all households in the district.', $lyceon_json$[{"key":"A","text":"critical"},{"key":"B","text":"nominal"},{"key":"C","text":"adjacent"},{"key":"D","text":"ornamental"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a drought-depleted reservoir triggering mandatory rationing, indicating the water supply has reached a dangerously low point. The word meaning at a point of crisis or extreme urgency fits this context precisely. The word meaning insignificant or existing in name only contradicts the severity implied by mandatory rationing. The word meaning nearby or next to describes spatial relationships, which is irrelevant to water levels. The word meaning decorative or serving an aesthetic purpose has no connection to emergency water supply conditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F3B27L', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the botanists'' hypothesis?', E'Botanists at the Kirstenbosch Research Station hypothesize that the unusual drought tolerance of the resurrection plant Myrothamnus flabellifolius is due primarily to its ability to accumulate high concentrations of the sugar trehalose in its leaf cells during water stress. Trehalose is thought to stabilize cell membranes by replacing water molecules in their structure, preventing the irreversible damage that typically occurs when plant tissues desiccate.', $lyceon_json$[{"key":"A","text":"Resurrection plant specimens with experimentally reduced trehalose levels suffered significantly more cellular damage during drought than untreated specimens."},{"key":"B","text":"Several unrelated desert plant species also display drought tolerance but accumulate sucrose rather than trehalose."},{"key":"C","text":"The resurrection plant grows most abundantly in rocky habitats where soil moisture is unpredictable."},{"key":"D","text":"Trehalose is commonly found in fungi and invertebrates but is rare among flowering plants."}]$lyceon_json$::jsonb, 'A', NULL, E'The botanists hypothesize that trehalose accumulation is responsible for the plant''s drought tolerance. A finding that reducing trehalose leads to greater cellular damage during drought would directly link trehalose levels to drought protection, supporting the causal claim. The finding that other drought-tolerant plants use sucrose instead of trehalose actually weakens the hypothesis by showing that trehalose is not necessary for drought tolerance. The observation about rocky habitats describes where the plant grows but does not address the mechanism of its drought tolerance. The finding about trehalose''s rarity in flowering plants provides taxonomic context but says nothing about whether trehalose is the agent of drought tolerance in this particular species.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FCM01S', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Harvested from the rocky intertidal zones of the Faroe Islands and dried on wooden racks throughout the brief subarctic ______ dulse seaweed has been a dietary staple for inhabitants of the North Atlantic archipelago for over eleven centuries.', $lyceon_json$[{"key":"A","text":"summer,"},{"key":"B","text":"summer."},{"key":"C","text":"summer;"},{"key":"D","text":"summer"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with a participial phrase (''Harvested from the rocky intertidal zones... brief subarctic summer'') that modifies the subject ''dulse seaweed.'' A comma is the only correct punctuation to separate an introductory participial phrase from the main clause it modifies. Placing a period after ''summer'' would turn the participial phrase into a sentence fragment, since it lacks an independent subject and finite verb. A semicolon requires independent clauses on both sides, but the participial phrase is not an independent clause. Omitting punctuation entirely fuses the modifier into the main clause without a grammatical boundary, creating a confusing run-on.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FUBXJB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Suspended from the vaulted ceiling of the seventeenth-century chapel and visible only when the afternoon light enters through the narrow eastern ______ a pair of gilded wooden angels, each carved with outstretched wings spanning nearly two meters—sculptures that art historians attribute to an anonymous Bavarian workshop active between 1680 and 1710.', $lyceon_json$[{"key":"A","text":"windows is"},{"key":"B","text":"windows are"},{"key":"C","text":"windows, is"},{"key":"D","text":"windows, are"}]$lyceon_json$::jsonb, 'A', NULL, E'This sentence uses inverted word order: the participial phrases ''Suspended from the vaulted ceiling...'' and ''visible only when the afternoon light enters through the narrow eastern windows'' precede the verb, and the true subject ''a pair of gilded wooden angels'' follows it. The phrase ''a pair'' is grammatically singular, so the verb must be singular: ''is.'' No comma should appear between ''windows'' and the verb because the introductory modifier flows directly into the main clause, and inserting a comma would incorrectly separate the verb from its modifying phrase without a grammatical reason. The option using ''are'' without a comma correctly omits the comma but uses a plural verb that disagrees with the singular subject ''a pair.'' The option using a comma followed by ''are'' both introduces an unnecessary comma and uses the wrong verb number. The option with a comma followed by ''is'' uses the correct verb number but inserts a comma that disrupts the connection between the introductory modifier and the inverted main clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GT5H85', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Linguist Saoirse Brennan has documented that speakers of Irish Gaelic in County Kerry increasingly code-switch into English when discussing technology-related topics, a pattern Brennan attributes to the dominance of English-language terminology in the technology sector. ______ Brennan observed that the same speakers consistently use Irish Gaelic without code-switching when discussing agriculture and fishing, domains in which Irish-language vocabulary has remained robust and actively transmitted across generations.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"As a result,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence describes speakers code-switching into English for technology topics, while the second sentence describes those same speakers not code-switching for agriculture and fishing topics. The transition "By contrast" correctly signals that the second sentence presents behavior that differs from what the first sentence describes. The option "Moreover" implies the second sentence adds a supporting detail to the same trend, but the second sentence describes a contrasting pattern rather than an extension of the first. The option "As a result" implies the consistent use of Irish Gaelic in agriculture is caused by the code-switching in technology, but the passage presents them as independently occurring patterns in different domains. The option "In other words" implies the second sentence restates the first, but the second sentence introduces a new observation about a different set of topics.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JV6DUZ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of entomologists at the University of Freiburg recently discovered that colonies of the European garden spider Araneus diadematus adjust the structural density of their webs in response to ambient wind speeds. In controlled wind-tunnel experiments, spiders exposed to sustained winds of 15 kilometers per hour produced webs with 37 percent more radial threads and significantly tighter spiral spacing than spiders in calm conditions. The researchers suggest that this architectural flexibility enables the spiders to maintain prey-capture efficiency across a range of environmental conditions, since denser webs are better able to absorb kinetic energy from wind gusts without rupturing.', $lyceon_json$[{"key":"A","text":"European garden spiders build denser webs in windier conditions, which likely helps them continue catching prey effectively."},{"key":"B","text":"European garden spiders produce the strongest webs of any orb-weaving species studied to date."},{"key":"C","text":"Wind tunnel experiments are the most reliable method for studying spider web construction."},{"key":"D","text":"Spider webs rupture less often in calm environments than in windy ones."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how European garden spiders increase web density in response to wind, and the researchers link this to maintaining prey-capture efficiency. The choice about spiders building denser webs in wind to sustain prey capture captures this central idea. The claim that these spiders produce the strongest webs of any orb-weaving species goes well beyond the passage, which discusses only one species and does not compare it to others. The assertion that wind tunnels are the most reliable method for studying web construction is not addressed in the passage, which merely describes the experimental setup without evaluating its superiority. The statement that webs rupture less in calm conditions, while possibly inferable, describes a secondary detail rather than the main idea of architectural flexibility for prey-capture efficiency.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KBDAVZ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Ornithologist Kenji Matsuda tracked the migration routes of 43 tagged bar-tailed godwits over three consecutive years and found that the birds followed nearly identical flight paths each autumn, deviating by no more than 12 kilometers from their previous year''s route despite crossing 11,000 kilometers of open ocean. Matsuda observed that even juvenile godwits making the journey for the first time closely replicated the routes of their parents. Given these findings, Matsuda would most likely agree that bar-tailed godwit migration routes are ________', $lyceon_json$[{"key":"A","text":"primarily determined by inherited navigational information rather than learned through individual trial and error."},{"key":"B","text":"chosen anew each year based on prevailing wind patterns at the time of departure."},{"key":"C","text":"impossible for researchers to predict with any accuracy from one year to the next."},{"key":"D","text":"significantly longer than those of all other migratory shorebird species."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that both experienced adults and first-time juveniles follow nearly identical routes year after year, with juveniles replicating parental paths without prior experience. This pattern supports the inference that navigational information is inherited rather than individually learned. The suggestion that routes are chosen anew based on wind patterns contradicts the finding of extreme route consistency across years. The claim that routes are unpredictable contradicts the passage''s core finding of minimal deviation between years. The assertion about routes being longer than all other shorebird species'' goes beyond the passage, which discusses only bar-tailed godwits and makes no comparative claims.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KONI1F', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Historian Claudia Ferreira has reexamined the economic records of seventeenth-century Portuguese trading outposts in the Indian Ocean and argues that the conventional portrait of these outposts as instruments of centralized imperial control is misleading. Ferreira''s analysis of customs ledgers from Goa, Mozambique, and Hormuz reveals that local administrators routinely negotiated independent trade agreements with neighboring polities, often in direct contradiction of directives from Lisbon. These agreements were not acts of rebellion, Ferreira contends, but pragmatic adaptations to local market conditions that Lisbon''s bureaucrats, working with information months out of date, could not have anticipated. The outposts, she concludes, functioned less as extensions of a coherent imperial strategy and more as semi-autonomous commercial actors whose practices were shaped primarily by regional economic realities.', $lyceon_json$[{"key":"A","text":"Portuguese trading outposts in the Indian Ocean operated with significant local autonomy driven by regional economic conditions rather than serving as tightly controlled extensions of imperial authority."},{"key":"B","text":"Administrators at Portuguese trading outposts frequently defied Lisbon's orders as part of organized resistance to imperial authority."},{"key":"C","text":"The Portuguese empire's trade network in the Indian Ocean collapsed because local administrators pursued their own commercial interests."},{"key":"D","text":"Customs ledgers from Goa, Mozambique, and Hormuz are unreliable as historical sources because they were maintained by administrators acting independently."}]$lyceon_json$::jsonb, 'A', NULL, E'Ferreira''s central argument is that Portuguese outposts acted as semi-autonomous commercial entities shaped by regional economics rather than as instruments of centralized imperial control. The choice about local autonomy driven by economic conditions captures this main idea. The characterization of administrators as engaged in organized resistance misreads Ferreira''s explicit statement that independent agreements were pragmatic adaptations, not acts of rebellion. The claim that the trade network collapsed because of independent administrators introduces an outcome the passage never mentions; Ferreira describes a functioning system, not a failing one. The assertion that customs ledgers are unreliable contradicts Ferreira''s own use of these ledgers as the evidentiary foundation for her argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LNLW96', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Svalbard Global Seed Vault—a reinforced concrete facility embedded deep within an Arctic mountainside on the Norwegian island of ______ currently stores over 1.2 million seed samples contributed by gene banks from nearly every nation on Earth.', $lyceon_json$[{"key":"A","text":"Spitsbergen,"},{"key":"B","text":"Spitsbergen—"},{"key":"C","text":"Spitsbergen;"},{"key":"D","text":"Spitsbergen"}]$lyceon_json$::jsonb, 'B', NULL, E'The parenthetical appositive ''a reinforced concrete facility embedded deep within an Arctic mountainside on the Norwegian island of Spitsbergen'' is opened with a dash after ''Vault.'' Proper punctuation symmetry requires a matching dash to close the parenthetical before ''currently.'' Using a comma to close a dash-opened parenthetical creates mismatched delimiters, which violates standard conventions. A semicolon would incorrectly sever the subject ''The Svalbard Global Seed Vault'' from its predicate ''currently stores,'' splitting the main clause at an inappropriate point. Omitting punctuation entirely leaves the parenthetical unclosed and merges it into the predicate, obscuring where the appositive ends and the main clause resumes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
