INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O88O33', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a music historian, if accurate, would most effectively support the scholar''s argument?', E'A musicology scholar contends that the Brazilian composer Heitor Villa-Lobos did not simply incorporate folk melodies into classical forms, as is commonly claimed, but instead developed an entirely original compositional syntax by abstracting structural principles—such as asymmetric phrase lengths, microtonal inflections, and collective rhythmic cycles—from rural Brazilian musical practices and embedding them at the level of harmonic and formal architecture. The scholar argues that this distinction matters because it reframes Villa-Lobos as a structural innovator rather than a mere arranger of folk tunes.', $lyceon_json$[{"key":"A","text":"\"Villa-Lobos's Bachianas Brasileiras deploy harmonic progressions built on the irregular metric groupings characteristic of northeastern Brazilian choro ensembles, producing formal structures that have no precedent in European concert music.\""},{"key":"B","text":"\"Villa-Lobos frequently quoted recognizable Brazilian folk songs in his orchestral works, transposing them into standard sonata-allegro form with minimal alteration.\""},{"key":"C","text":"\"Villa-Lobos's international reputation rested largely on his personal charisma and his vigorous promotion of Brazilian national identity at diplomatic events.\""},{"key":"D","text":"\"While Villa-Lobos admired J. S. Bach, his knowledge of European harmonic theory was largely self-taught and occasionally idiosyncratic.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The scholar argues that Villa-Lobos abstracted structural principles from Brazilian folk music and embedded them in formal architecture, making him a structural innovator. The quotation about harmonic progressions derived from irregular metric groupings producing unprecedented formal structures directly supports this characterization by illustrating structural-level innovation drawn from folk practice. The quotation about quoting folk songs in sonata-allegro form with minimal alteration supports the conventional view the scholar is challenging, not the scholar''s own argument. The quotation about Villa-Lobos''s personal charisma and diplomacy addresses his reputation rather than his compositional technique and is irrelevant to the structural-innovation claim. The quotation about self-taught harmonic knowledge provides biographical context but does not demonstrate that Villa-Lobos developed a new compositional syntax from Brazilian musical principles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P7PGOG', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Historian Claudette Mirande contends that the Venetian Republic''s diplomatic corps in the sixteenth century functioned less as messengers conveying fixed positions than as ______ agents who shaped policy in real time through their on-the-ground assessments, often committing the Republic to stances the Senate had never formally endorsed.', $lyceon_json$[{"key":"A","text":"autonomous"},{"key":"B","text":"ceremonial"},{"key":"C","text":"subordinate"},{"key":"D","text":"ancillary"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes diplomats who shaped policy independently through their own assessments and committed the Republic to positions the Senate had not endorsed, indicating they acted with self-directed authority. The word meaning self-governing or acting independently captures this precisely. The word meaning relating to formal ritual or ceremony suggests diplomats served a purely symbolic function, which contradicts their active shaping of policy. The word meaning under the authority or control of another directly opposes the passage''s emphasis on diplomats acting beyond their official mandate. The word meaning providing supplementary support suggests a minor, assisting role, whereas the passage portrays diplomats as primary drivers of policy rather than secondary helpers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SFA072', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a proposal for a campus sustainability committee and wants to argue that composting programs are more cost-effective than their reputation suggests. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SH7ZH3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Honeybees communicate the location of food sources through a behavior known as the waggle dance. A forager returning to the hive performs a series of movements that indicate both the direction and distance of a nectar-rich site. [underlined: The angle of the dance relative to the vertical surface of the comb corresponds to the angle between the sun and the food source.] Other bees observing the dance can then fly directly to the indicated location.', $lyceon_json$[{"key":"A","text":"It explains a specific mechanism by which the waggle dance conveys directional information."},{"key":"B","text":"It introduces an alternative hypothesis about how bees locate food sources."},{"key":"C","text":"It describes a limitation of the waggle dance as a communication method."},{"key":"D","text":"It provides background on the general anatomy of a beehive."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence specifies how the angle of the dance on the comb maps to the angle between the sun and the food source, elaborating on the mechanism behind the directional information mentioned in the preceding sentence. This is a concrete explanation of how the dance conveys direction. The option about introducing an alternative hypothesis mischaracterizes the sentence; it elaborates on the established waggle dance, not a competing explanation. The option about describing a limitation is unsupported; the sentence explains how the dance works effectively, not where it falls short. The option about beehive anatomy misidentifies the subject; the comb is mentioned only as the surface on which the dance occurs, not as a topic of discussion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SLHZHR', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Sociologist Ingrid Dahl studied public trust in autonomous vehicle technology across nine Scandinavian municipalities and found that trust levels were significantly higher in municipalities that had conducted small-scale autonomous shuttle pilot programs than in municipalities that had not. Interestingly, the increased trust was not limited to residents who had personally ridden the shuttles; even residents who had only observed the shuttles operating in their neighborhoods reported trust levels nearly as high as those of actual riders. Dahl suggests that direct visual exposure to autonomous vehicles operating safely in familiar settings reduces the abstract anxiety that many people associate with the technology. Based on Dahl''s findings, one would expect that a municipality seeking to increase public acceptance of autonomous vehicles would benefit most from ________', $lyceon_json$[{"key":"A","text":"deploying a small number of autonomous shuttles on visible, well-traveled local routes rather than distributing informational brochures about the technology's safety record."},{"key":"B","text":"restricting autonomous shuttle operations to industrial areas where few residents would observe them."},{"key":"C","text":"conducting a large-scale media campaign emphasizing the statistical safety advantages of autonomous vehicles over human-driven ones."},{"key":"D","text":"requiring all residents to complete a mandatory ride in an autonomous shuttle before forming an opinion about the technology."}]$lyceon_json$::jsonb, 'A', NULL, E'Dahl''s findings indicate that direct visual exposure to autonomous vehicles operating safely in familiar settings—not just personal ridership—drives trust. Deploying shuttles on visible, well-traveled routes maximizes the visual exposure Dahl identifies as the key mechanism, making this the most logical application of her research. Restricting operations to industrial areas would minimize the visual exposure Dahl found to be critical, contradicting her findings. A media campaign providing statistical safety information addresses abstract knowledge rather than the direct visual exposure Dahl identifies as the trust-building mechanism. Requiring mandatory rides goes beyond what Dahl''s research supports, since she found that mere observation was nearly as effective as ridership, making mandatory participation unnecessary.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UA1GV7', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding would most directly undermine the explanation proposed by Kharazi and Strand?', E'Environmental scientists Kharazi and Strand investigated why coral reefs near volcanic islands in the western Pacific exhibit higher species diversity than reefs of comparable size in non-volcanic regions. They propose that periodic low-level volcanic activity enriches surrounding waters with trace minerals—particularly iron and manganese—that stimulate phytoplankton growth, which in turn supports a more complex food web capable of sustaining a greater variety of coral-associated species. Kharazi and Strand emphasize that this mineral-enrichment effect operates only at low eruption intensities; major eruptions, they note, smother reefs with ash and reduce diversity.', $lyceon_json$[{"key":"A","text":"Reefs near volcanic islands that have been dormant for over five centuries display species diversity levels equal to those of reefs near volcanically active islands in the same region."},{"key":"B","text":"Phytoplankton communities near volcanic islands contain species not found in non-volcanic reef systems."},{"key":"C","text":"Major volcanic eruptions in the western Pacific have become less frequent over the past century."},{"key":"D","text":"Some non-volcanic reefs in the eastern Pacific also show high species diversity, but these reefs are located near deep-ocean upwelling zones."}]$lyceon_json$::jsonb, 'A', NULL, E'Kharazi and Strand attribute the higher diversity near volcanic islands to ongoing low-level volcanic mineral enrichment. If reefs near long-dormant volcanoes—where no recent mineral enrichment has occurred—show diversity equal to reefs near active volcanoes, the mineral-enrichment mechanism cannot account for the diversity difference, directly undermining the proposed explanation. The finding about unique phytoplankton species near volcanic islands would be consistent with the mineral-enrichment hypothesis rather than undermining it. The finding about declining eruption frequency concerns major eruptions, which Kharazi and Strand already distinguish from the low-level activity central to their hypothesis. The finding about non-volcanic reefs near upwelling zones shows that other nutrient sources can also produce high diversity, but this does not undermine the claim that volcanic minerals are the operative mechanism near volcanic islands specifically—it merely identifies an alternative pathway elsewhere.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X0LOF3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'Cognitive scientist Lila Ranganathan proposes that human moral reasoning relies on two distinct neural systems: a fast, intuitive system that generates immediate emotional responses to perceived harm, and a slower, deliberative system that evaluates consequences and applies abstract principles. Ranganathan argues that most everyday moral judgments arise from the intuitive system, with the deliberative system engaged only when intuitions conflict or when a situation is sufficiently novel to lack established emotional templates.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y3QGGT', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Behavioral economist Renata Oliveira has demonstrated that workers in São Paulo''s informal recycling cooperatives sort materials more accurately when paid per kilogram of correctly classified output rather than per hour worked. ______ Oliveira cautions that this accuracy incentive also led sorters to reject borderline-recyclable items they would previously have accepted, reducing the total volume of material diverted from landfills by an estimated 11 percent.', $lyceon_json$[{"key":"A","text":"In fact,"},{"key":"B","text":"That said,"},{"key":"C","text":"To illustrate,"},{"key":"D","text":"Subsequently,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence presents a positive finding — accuracy improved under per-kilogram pay. The second sentence introduces an unexpected downside: the same incentive reduced total material diverted from landfills. The transition "That said" correctly signals that the speaker is qualifying or tempering the preceding positive claim with a complication. The option "In fact" typically intensifies or confirms the preceding point, but the second sentence does not reinforce the accuracy improvement — it introduces an unintended negative consequence. The option "To illustrate" implies the second sentence provides an example of the accuracy improvement, but the second sentence describes a separate, adverse outcome rather than exemplifying the first sentence''s finding. The option "Subsequently" implies mere chronological sequence, but the logical relationship here is one of concession — the second sentence qualifies the first rather than simply reporting what happened next.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YD8QSM', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Tariq Bensalah studied wage-setting behavior among employers in labor markets with few competing firms—so-called monopsonistic markets—and found that employers in such markets set wages significantly below workers'' estimated marginal productivity. However, Bensalah also discovered an unexpected moderating factor: in monopsonistic markets where a substantial share of the workforce belonged to community-based mutual aid organizations, the wage gap between productivity and actual pay was considerably smaller than in otherwise similar markets without such organizations. Bensalah argues that mutual aid networks, while lacking the formal bargaining power of labor unions, create an informal information-sharing infrastructure that allows workers to collectively identify and respond to below-market wage offers. If Bensalah''s interpretation is correct, one would expect that in monopsonistic labor markets where mutual aid organizations have recently dissolved, employers would ________', $lyceon_json$[{"key":"A","text":"gradually widen the gap between wages and worker productivity, since workers' ability to coordinate responses to low offers would diminish."},{"key":"B","text":"raise wages to match worker productivity in order to attract applicants from outside the local labor market."},{"key":"C","text":"maintain wages at the same level as before the dissolution, since formal employment contracts would prevent any change."},{"key":"D","text":"immediately face increased competition from new firms entering the market to exploit the now-unorganized labor supply."}]$lyceon_json$::jsonb, 'A', NULL, E'Bensalah''s framework holds that mutual aid organizations moderate the wage-productivity gap by enabling informal coordination among workers. If those organizations dissolve, the coordination mechanism disappears, logically allowing employers to depress wages further and widen the gap—consistent with the pattern observed in markets without such organizations. The prediction that employers would raise wages to attract outside workers assumes competitive labor market dynamics that Bensalah''s monopsonistic framework specifically precludes; in monopsonistic markets, few competing employers exist. The prediction that wages would remain unchanged ignores Bensalah''s finding that the organizations were actively responsible for the smaller wage gap; their absence removes the moderating force. The prediction about new firms entering the market introduces a competitive response that contradicts the monopsonistic conditions Bensalah describes, where few firms compete for labor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YL3B1G', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geologist''s preliminary report, which drew on seventeen months of fieldwork in the Deccan Traps and which, after incorporating seismic data collected by a consortium of nine ______ revised its initial estimate of the volcanic province''s total basalt volume upward by nearly forty percent.', $lyceon_json$[{"key":"A","text":"universities, revised"},{"key":"B","text":"universities revised"},{"key":"C","text":"universities; revised"},{"key":"D","text":"universities. Revised"}]$lyceon_json$::jsonb, 'A', NULL, E'This sentence contains a deeply nested structure: the main clause (''The geologist''s preliminary report... revised its initial estimate...'') encloses a nonrestrictive relative clause (''which drew on seventeen months... and which... revised''), and within that relative clause, a parenthetical adverbial phrase (''after incorporating seismic data collected by a consortium of nine universities'') is set off by commas. Because this parenthetical opens with a comma after the second ''which,'' it must close with a comma after ''universities'' so that the relative clause can continue with ''revised.'' Omitting the closing comma leaves the parenthetical unclosed, creating a confusing run-on within the relative clause that obscures the sentence''s grammatical relationships. A semicolon would fragment the interior of the relative clause at an inappropriate point. A period after ''universities'' would sever the relative clause from the main clause entirely, producing a fragment beginning with ''Revised'' that lacks a grammatical subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
